import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.Capd0F6S.js";var i=JSON.parse(`{"title":"程序执行原理（科普）","description":"","frontmatter":{},"headers":[],"relativePath":"python/python-basics/program-execution-principles.md","filePath":"python/python-basics/program-execution-principles.md"}`),a={name:`python/python-basics/program-execution-principles.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="程序执行原理-科普" tabindex="-1">程序执行原理（科普） <a class="header-anchor" href="#程序执行原理-科普" aria-label="Permalink to “程序执行原理（科普）”">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h2><ul><li>计算机中的 <strong>三大件</strong></li><li>程序执行的原理</li><li>程序的作用</li></ul><h2 id="_01-计算机中的三大件" tabindex="-1">01. 计算机中的三大件 <a class="header-anchor" href="#_01-计算机中的三大件" aria-label="Permalink to “01. 计算机中的三大件”">​</a></h2><p>计算机中包含有较多的硬件，但是一个程序要运行，有 <strong>三个</strong> 核心的硬件，分别是：</p><ol><li><strong>CPU</strong><ul><li>中央处理器，是一块超大规模的集成电路</li><li>负责 <strong>处理数据</strong>／<strong>计算</strong></li></ul></li><li><strong>内存</strong><ul><li><strong>临时</strong> 存储数据（断电之后，数据会消失）</li><li>速度快</li><li>空间小（单位价格高）</li></ul></li><li><strong>硬盘</strong><ul><li><strong>永久</strong> 存储数据</li><li>速度慢</li><li>空间大（单位价格低）</li></ul></li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">CPU</th><th style="text-align:center;">内存</th><th style="text-align:center;">硬盘</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="/blog-notes/assets/CPU.D1kEbZIU.jpg" alt="CPU-w200" width="1920" height="1440"></td><td style="text-align:center;"><img src="/blog-notes/assets/%E5%86%85%E5%AD%98%E6%9D%A1.Ce-EpF-J.png" alt="内存条-w200" width="1689" height="1037"></td><td style="text-align:center;"><img src="/blog-notes/assets/%E7%A1%AC%E7%9B%98.D_wRn8dt.jpg" alt="硬盘-w200" width="1024" height="685"></td></tr></tbody></table><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to “思考题”">​</a></h3><ol><li>计算机中哪一个硬件设备负责执行程序？ <ul><li><strong>CPU</strong></li></ul></li><li><strong>内存</strong> 的速度快还是 <strong>硬盘</strong> 的速度快？ <ul><li><strong>内存</strong></li></ul></li><li>我们的程序是安装在内存中的，还是安装在硬盘中的？ <ul><li>硬盘</li></ul></li><li><strong>我买了一个内存条，有 500G 的空间！！！</strong>，这句话对吗？ <ul><li>不对，内存条通常只有 <code>4G</code> / <code>8G</code> / <code>16G</code> / <code>32G</code></li></ul></li><li><strong>计算机关机之后，内存中的数据都会消失</strong>，这句话对吗？ <ul><li>正确</li></ul></li></ol><h2 id="_02-程序执行的原理" tabindex="-1">02. 程序执行的原理 <a class="header-anchor" href="#_02-程序执行的原理" aria-label="Permalink to “02. 程序执行的原理”">​</a></h2><p><img src="/blog-notes/assets/001_%E7%A8%8B%E5%BA%8F%E6%89%A7%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.D_aCdEFo.png" alt="001_程序执行示意图-w" width="758" height="186"></p><ol><li>程序 <strong>运行之前</strong>，程序是 <strong>保存在硬盘</strong> 中的</li><li>当要运行一个程序时 <ul><li>操作系统会首先让 <strong>CPU</strong> 把程序复制到 <strong>内存</strong> 中</li><li><strong>CPU</strong> 执行 <strong>内存</strong> 中的 <strong>程序代码</strong></li></ul></li></ol><blockquote><p><strong>程序要执行，首先要被加载到内存</strong></p></blockquote><h3 id="_2-1-python-程序执行原理" tabindex="-1">2.1 Python 程序执行原理 <a class="header-anchor" href="#_2-1-python-程序执行原理" aria-label="Permalink to “2.1 Python 程序执行原理”">​</a></h3><p><img src="/blog-notes/assets/003_Python%E7%A8%8B%E5%BA%8F%E6%89%A7%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.UaTla12r.png" alt="003_Python程序执行示意图" width="758" height="186"></p><ol><li>操作系统会首先让 <strong>CPU</strong> 把 <strong>Python 解释器</strong> 的程序复制到 <strong>内存</strong> 中</li><li><strong>Python 解释器</strong> 根据语法规则，<strong>从上向下</strong> 让 <strong>CPU</strong> 翻译 <strong>Python 程序中的代码</strong></li><li><strong>CPU</strong> 负责执行翻译完成的代码</li></ol><h4 id="python-的解释器有多大" tabindex="-1">Python 的解释器有多大？ <a class="header-anchor" href="#python-的解释器有多大" aria-label="Permalink to “Python 的解释器有多大？”">​</a></h4><ul><li>执行以下终端命令可以查看 Python 解释器的大小</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 1. 确认解释器所在位置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 2. 查看 python 文件大小(只是一个软链接)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/python</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 3. 查看具体文件大小</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/python2.7</span></span></code></pre></div><blockquote><p>提示：建立 <strong>软链接</strong> 的目的，是为了方便使用者不用记住使用的解释器是 <strong>哪一个具体版本</strong></p></blockquote><h2 id="_03-程序的作用" tabindex="-1">03. 程序的作用 <a class="header-anchor" href="#_03-程序的作用" aria-label="Permalink to “03. 程序的作用”">​</a></h2><blockquote><p>程序就是 <strong>用来处理数据</strong> 的！</p></blockquote><ul><li><strong>新闻软件</strong> 提供的 <strong>新闻内容、评论……</strong> 是数据</li><li><strong>电商软件</strong> 提供的 <strong>商品信息、配送信息……</strong> 是数据</li><li><strong>运动类软件</strong> 提供的 <strong>运动数据……</strong> 是数据</li><li><strong>地图类软件</strong> 提供的 <strong>地图信息、定位信息、车辆信息……</strong> 是数据</li><li><strong>即时通讯软件</strong> 提供的 <strong>聊天信息、好友信息……</strong> 是数据</li><li>……</li></ul><h3 id="_3-1-思考-qq-程序的启动过程" tabindex="-1">3.1 思考 QQ 程序的启动过程 <a class="header-anchor" href="#_3-1-思考-qq-程序的启动过程" aria-label="Permalink to “3.1 思考 QQ 程序的启动过程”">​</a></h3><ol><li>QQ 在<strong>运行之前</strong>，是保存在 <strong>硬盘</strong> 中的</li><li><strong>运行之后</strong>，QQ 程序就会被加载到 <strong>内存</strong> 中了</li></ol><p><img src="/blog-notes/assets/003_QQ%E7%99%BB%E9%99%86%E7%95%8C%E9%9D%A2.3QjGaAkH.png" alt="003_QQ登陆界面-w248" width="496" height="632"></p><h3 id="_3-2-思考-qq-程序的-登录-过程" tabindex="-1">3.2 思考 QQ 程序的 <strong>登录</strong> 过程 <a class="header-anchor" href="#_3-2-思考-qq-程序的-登录-过程" aria-label="Permalink to “3.2 思考 QQ 程序的 登录 过程”">​</a></h3><ol><li>读取用户输入的 <strong>QQ 号码</strong></li><li>读取用户输入的 <strong>QQ 密码</strong></li><li>将 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 发送给腾讯的服务器，等待服务器确认用户信息</li></ol><h4 id="思考-1" tabindex="-1">思考 1 <a class="header-anchor" href="#思考-1" aria-label="Permalink to “思考 1”">​</a></h4><blockquote><p>在 QQ 这个程序将 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 发送给服务器之前，<strong>是否需要先存储一下 QQ 号码 和 密码?</strong></p></blockquote><p><strong>答案</strong></p><p>肯定需要！—— 否则 QQ 这个程序就不知道把什么内容发送给服务器了！</p><h4 id="思考-2" tabindex="-1">思考 2 <a class="header-anchor" href="#思考-2" aria-label="Permalink to “思考 2”">​</a></h4><blockquote><p>QQ 这个程序把 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 保存在哪里？</p></blockquote><p><strong>答案</strong></p><p>保存在 <strong>内存</strong> 中，因为 QQ 程序自己就在内存中</p><h4 id="思考-3" tabindex="-1">思考 3 <a class="header-anchor" href="#思考-3" aria-label="Permalink to “思考 3”">​</a></h4><blockquote><p>QQ 这个程序是怎么保存用户的 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 的？</p></blockquote><p><strong>答案</strong></p><ol><li>在内存中为 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 各自分配一块空间 <ul><li>在 QQ 程序结束之前，这两块空间是由 QQ 程序负责管理的，其他任何程序都不允许使用</li><li>在 QQ 自己使用完成之前，这两块空间始终都只负责保存 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong></li></ul></li><li>使用一个 <strong>别名</strong> 标记 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 在内存中的位置</li></ol><p><img src="/blog-notes/assets/004_QQ%E5%8F%B7%E7%A0%81%E5%92%8C%E5%AF%86%E7%A0%81%E5%86%85%E5%AD%98%E7%A4%BA%E6%84%8F%E5%9B%BE.CsvzEVdn.png" alt="004_QQ号码和密码内存示意图" width="315" height="431"></p><blockquote><ul><li>在程序内部，为 <strong>QQ 号码</strong> 和 <strong>QQ 密码</strong> 在内存中分配的空间就叫做 <strong>变量</strong></li><li><strong>程序就是用来处理数据的，而变量就是用来存储数据的</strong></li></ul></blockquote>`,42)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};